const ZadAudio={current:null,currentId:null,queue:[],play(audioEl,id){if(!audioEl)return;if(this.current&&this.current!==audioEl){this.current.pause();this._updateButtonState(this.currentId,false)}this.current=audioEl;this.currentId=id;const playPromise=audioEl.play();if(playPromise!==undefined){playPromise.then(()=>this._updateButtonState(id,true)).catch(err=>{console.log("[Audio] autoplay blocked:",err.name);this._updateButtonState(id,false);if(typeof showToast==="function"){showToast("▶️ اضغط مرة أخرى للتشغيل")}})}},pause(){if(this.current){this.current.pause();this._updateButtonState(this.currentId,false)}},toggle(audioEl,id){if(this.current===audioEl&&!audioEl.paused){this.pause()}else{this.play(audioEl,id)}},stop(){if(this.current){this.current.pause();this.current.currentTime=0;this._updateButtonState(this.currentId,false);this.current=null;this.currentId=null}},_updateButtonState(id,playing){document.querySelectorAll(`[data-audio-btn="${id}"]`).forEach(btn=>{btn.textContent=playing?"⏸️":"▶️";btn.classList.toggle("playing",playing)})},registerAll(){document.querySelectorAll("audio").forEach((audio,i)=>{if(audio._zadManaged)return;audio._zadManaged=true;const id=audio.id||audio.dataset.audioId||`audio-${i}`;audio.addEventListener("ended",()=>{this._updateButtonState(id,false);if(this.current===audio){this.current=null;this.currentId=null}this._playNext()});audio.addEventListener("play",()=>{if(this.current&&this.current!==audio){this.current.pause()}this.current=audio;this.currentId=id;this._updateButtonState(id,true)});audio.addEventListener("pause",()=>{this._updateButtonState(id,false)})})},_playNext(){if(this.queue.length>0){const next=this.queue.shift();if(next.audio)this.play(next.audio,next.id)}},enqueue(audioEl,id){this.queue.push({audio:audioEl,id:id})},cleanup(){this.stop();this.queue=[]}};function wireAudioButtons(){document.querySelectorAll("[data-audio-target]").forEach(btn=>{if(btn._zadAudioWired)return;btn._zadAudioWired=true;btn.addEventListener("click",()=>{const targetId=btn.dataset.audioTarget;const audio=document.getElementById(targetId);if(audio)ZadAudio.toggle(audio,targetId)})})}window.addEventListener("pagehide",()=>ZadAudio.cleanup());document.addEventListener("visibilitychange",()=>{});document.addEventListener("DOMContentLoaded",()=>{ZadAudio.registerAll();wireAudioButtons();const observer=new MutationObserver(()=>{ZadAudio.registerAll();wireAudioButtons()});observer.observe(document.body,{childList:true,subtree:true});console.log("[ZadAudio] ✅ مدير الصوت المركزي جاهز")});window.ZadAudio=ZadAudio;